CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;
CREATE SEQUENCE "VehicleSequence" START WITH 1 INCREMENT BY 1 NO CYCLE;

CREATE TABLE accounts (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Email" text NOT NULL,
    "Nick" text,
    "Kind" text NOT NULL,
    "Title" text NOT NULL,
    "GranteeId" integer NOT NULL,
    "Rank" integer NOT NULL,
    "Score" integer,
    "DeletedOn" date,
    "CreatedAt" timestamp with time zone NOT NULL,
    "Tags" text[] NOT NULL,
    "Period" daterange NOT NULL,
    "Contact_City" text NOT NULL,
    "Contact_Phone" text NOT NULL,
    payload jsonb NOT NULL,
    prefs jsonb NOT NULL,
    CONSTRAINT "PK_accounts" PRIMARY KEY ("Id")
);

CREATE TABLE boats (
    "Id" integer NOT NULL DEFAULT (nextval('"VehicleSequence"')),
    "Plate" text NOT NULL,
    "OwnerId" integer NOT NULL,
    CONSTRAINT "PK_boats" PRIMARY KEY ("Id")
);

CREATE TABLE cars (
    "Id" integer NOT NULL DEFAULT (nextval('"VehicleSequence"')),
    "Plate" text NOT NULL,
    "OwnerId" integer NOT NULL,
    CONSTRAINT "PK_cars" PRIMARY KEY ("Id")
);

CREATE TABLE vehicles (
    "Id" integer NOT NULL DEFAULT (nextval('"VehicleSequence"')),
    "Plate" text NOT NULL,
    "OwnerId" integer NOT NULL,
    CONSTRAINT "PK_vehicles" PRIMARY KEY ("Id")
);

CREATE INDEX "IX_accounts_Contact_City" ON accounts ("Contact_City");

CREATE UNIQUE INDEX ux_account_phone ON accounts ("Contact_Phone") WHERE "DeletedOn" IS NULL;

CREATE INDEX "IX_accounts_prefsTheme" ON accounts (("prefs" ->> 'Theme'));

CREATE UNIQUE INDEX ux_account_email_active ON accounts ("Email") WHERE "DeletedOn" IS NULL;

CREATE INDEX ix_account_email_all ON accounts ("Email");

CREATE UNIQUE INDEX "IX_accounts_GranteeId_Kind" ON accounts ("GranteeId", "Kind");

CREATE INDEX "IX_accounts_Kind_Rank_Score" ON accounts ("Kind", "Rank" DESC, "Score" NULLS FIRST);

CREATE INDEX "IX_accounts_Title_Nick" ON accounts ("Title" COLLATE "C", "Nick") INCLUDE ("Rank", "Contact_City") WITH (deduplicate_items=false, fillfactor=70);

CREATE UNIQUE INDEX ux_account_nick ON accounts ("Nick" text_pattern_ops) NULLS NOT DISTINCT;

COMMIT;

CREATE INDEX CONCURRENTLY ix_account_rank ON accounts ("Rank");

START TRANSACTION;
CREATE INDEX "IX_accounts_Tags" ON accounts USING gin ("Tags");

CREATE INDEX "IX_accounts_Period" ON accounts USING gist ("Period");

CREATE INDEX "IX_accounts_CreatedAt" ON accounts USING brin ("CreatedAt") WITH (pages_per_range=16);

CREATE INDEX ix_account_title_sp ON accounts USING spgist ("Title");

CREATE INDEX ix_account_kind_hash ON accounts USING hash ("Kind");

CREATE INDEX "IX_accounts_lowerEmail" ON accounts ((lower("Email")));

CREATE UNIQUE INDEX "IX_accounts_lowerTitle" ON accounts ((lower("Title")));

CREATE INDEX "IX_accounts_coalesceNickKindTitle" ON accounts ((((coalesce("Nick", "Kind") || ' ') || "Title")));

CREATE UNIQUE INDEX ux_account_kind_title ON accounts (("Kind"), (upper("Title")) DESC NULLS LAST) WHERE "Rank" > 0;

CREATE INDEX ix_account_kind_live ON accounts ("Kind") WHERE "DeletedOn" IS NULL;

CREATE INDEX "IX_accounts_GranteeId_Rank" ON accounts ("GranteeId", "Rank") WHERE ("DeletedOn" IS NOT NULL AND "Kind" = 'federated');

CREATE INDEX "IX_accounts_upperEmail" ON accounts ((upper("Email"))) WHERE ("Nick" <> 'blocked' OR "Nick" IS NULL);

CREATE UNIQUE INDEX ux_account_level ON accounts ((CAST("prefs" ->> 'Level' AS integer)));

CREATE INDEX "IX_accounts_prefsAddressZip" ON accounts (("prefs" #>> '{Address,Zip}'));

CREATE INDEX "IX_accounts_Kind_prefsActive" ON accounts ("Kind", (CAST("prefs" ->> 'Active' AS boolean))) WHERE (CAST("prefs" ->> 'Level' AS integer)) > 3;

CREATE INDEX "IX_accounts_payload" ON accounts USING gin (payload jsonb_path_ops);

CREATE UNIQUE INDEX ux_vehicle_plate ON vehicles ("Plate");

CREATE UNIQUE INDEX ux_vehicle_plate_boats ON boats ("Plate");

CREATE UNIQUE INDEX ux_vehicle_plate_cars ON cars ("Plate");

CREATE INDEX "IX_vehicles_OwnerId" ON vehicles ("OwnerId");

CREATE INDEX "IX_boats_OwnerId" ON boats ("OwnerId");

CREATE INDEX "IX_cars_OwnerId" ON cars ("OwnerId");

COMMIT;

INSERT INTO "__EFMigrationsHistory" ("MigrationId", "ProductVersion")
VALUES ('20260101000000_Initial', '10.0.15');

